head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07230";
scwin.dts_List = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07230.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_searchWord", fn: function () { return String((dma_pageContext.get("searchWord") ?? "")); } },
        { childId: "cal_startDate", fn: function () { return String((dma_pageContext.get("startDate") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } },
        { childId: "__rb0", fn: function () { return " 전체 " + String(dma_pageResult.get("total")) + "건 (" + String(dma_pageResult.get("currentPage")) + "/" + String(dma_pageResult.get("pageCount")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_changePage();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_startDate_onblur
 * @description cal_startDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_startDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_startDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07230.cal_startDate_onblur' }); }
};

/**
 * @method
 * @name cal_endDate_onblur
 * @description cal_endDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_endDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_endDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07230.cal_endDate_onblur' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07230.btn_search_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_pageSize_onchange = function(e){
    try {
        fn_Search();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07230.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_bbsList_oncellclick
 * @description grd_bbsList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_bbsList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_bbsList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_bbsList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.searchCommentLetterView(r["contnId"], r["contnGrpId"], r["ansObjContnId"], r["listInvstgBbsTpCd"], r["contnAttachSeq"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_bbsList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_goWriteBBS_onclick
 * @description btn_goWriteBBS 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goWriteBBS_onclick = async function(e){
    try {
        await scwin.goWriteBBS()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07230.btn_goWriteBBS_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_122_onclick
 * @description krxpage_pagenavigator_122 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_122_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_changePageReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_122.page' }); } await scwin.tx_changePage(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_List
 * @description script dts List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_List = async function () {
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, BBS_TP_CD, LD_MKT_TP"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, BBS_TP_CD, LD_MKT_TP", unresolved: "query_param:SCREN_ID,SCREN_PROCES_TP_CD,BBS_TP_CD,LD_MKT_TP" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/lstinvstg/ListCommBoard.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07230.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name tx_changePage
 * @description change Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_changePage = async function () {
    const sbmOptions = {
        id: "tx_changePage",
        method: "post",
        action: "/lstinvstg/bbs.do",
        ref: "dma_changePageReq",
        target: "dlt_bbsList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_122").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_goWriteBBS
 * @description go Write BBS 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWriteBBS = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — bbs.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — bbs.do", unresolved: "action:bbs.do" };
};

/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — bbs.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — bbs.do", unresolved: "action:bbs.do" };
};

/**
 * @method
 * @name tx_fn_SearchCommentLetterView
 * @description Search Comment Letter View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchCommentLetterView = async function () {
    // ⛔주소를 정할 수 없다 — as-is 문서 위치를 못 찾았다(⛔못 쟀다 — as-is JSP 위치 미상).
    //   추정 주소로 내보내면 «엉뚱한 곳으로 조용히» 나간다. 불릴 때 드러나게 실패시킨다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "제출 주소를 찾지 못했습니다(전환 미완) — bbs.do"
    throw { bizMessage: "제출 주소를 찾지 못했습니다(전환 미완) — bbs.do", unresolved: "action:bbs.do" };
};

/**
 * @method
 * @name changePage
 * @description change Page 처리
 * @param {*} ver1 ver1
 * @param {*} ver2 ver2
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changePage = async function (ver1, ver2) {
    const form = (document.moveForm || { elements: [] });
    if ('1' === ver1) {
        $c.util.getComponent('dma_changePageReq').set('nowPage', ver2);
    } else {
        if ('2' === ver1) {
            $c.util.getComponent('dma_changePageReq').set('nowPage', '20');
            $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'loadDetail');
        } else {
            if ('3' === ver1) {
                $c.util.getComponent('dma_changePageReq').set('nowPage', '30');
                form.action = '/lstinvstg/bbs.do';
                $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'searchCommentLetterList');
            } else {
                if ('4' === ver1) {
                    $c.util.getComponent('dma_changePageReq').set('nowPage', '40');
                }
            }
        }
    }
    await scwin.tx_changePage();
};

/**
 * @method
 * @name goWriteBBS
 * @description go Write BBS 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWriteBBS = async function () {
    const frm = (document.CommentLetterInfoForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'writeCommentLetter');
    const nr = await scwin.tx_fn_goWriteBBS();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil51310/jldfil51310.xml", { "method": 'writeCommentLetter' });
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.CommentLetterListForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'searchCommentLetterList');
    const nr = await scwin.tx_fn_search();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil51300/jldfil51300.xml", { "method": 'searchCommentLetterList' });
    }
};

/**
 * @method
 * @name searchCommentLetterView
 * @description search Comment Letter View 처리
 * @param {String} contnId contnId
 * @param {String} contnGrpId contnGrpId
 * @param {String} ansObjContnId ansObjContnId
 * @param {String} listInvstgBbsTpCd listInvstgBbsTpCd
 * @param {*} contnAttachSeq contnAttachSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCommentLetterView = async function (contnId, contnGrpId, ansObjContnId, listInvstgBbsTpCd, contnAttachSeq) {
    const frm = (document.CommentLetterListForm || { elements: [] });
    frm.action = 'bbs.do';
    $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'searchCommentLetterView');
    $c.util.getComponent('dma_changePageReq').set('contnId', contnId);
    $c.util.getComponent('dma_changePageReq').set('contnGrpId', contnGrpId);
    $c.util.getComponent('dma_changePageReq').set('ansObjContnId', ansObjContnId);
    $c.util.getComponent('dma_changePageReq').set('listInvstgBbsTpCd', listInvstgBbsTpCd);
    $c.util.getComponent('dma_changePageReq').set('contnAttachSeq', contnAttachSeq);
    const nr = await scwin.tx_fn_SearchCommentLetterView();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil51320/jldfil51320.xml", { "method": 'searchCommentLetterView', "contnId": contnId, "contnGrpId": contnGrpId, "ansObjContnId": ansObjContnId, "listInvstgBbsTpCd": listInvstgBbsTpCd, "contnAttachSeq": contnAttachSeq });
    }
};
